// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.gca;

import java.lang.ref.SoftReference;
import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GcAlternativesDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        ConnectionPool pool = new ConnectionPool(2); // reuse 2 connections

        // ALTERNATIVE 1 + 2: pooling + try-with-resources (deterministic return).
        for (int i = 0; i < 5; i++) {
            try (PooledLedgerConnection conn = pool.borrow()) {
                conn.transfer(rajesh, priya, new BigDecimal("10000"));
            } // connection returned to pool HERE, no allocation churn
        }

        // ALTERNATIVE 3: soft-reference cache the JVM can reclaim under pressure.
        SoftReference<String> snapshot =
                new SoftReference<>("Rajesh=" + rajesh.getBalance() + ",Priya=" + priya.getBalance());
        log.info(() -> "Soft snapshot: " + snapshot.get());

        // We deliberately DO NOT call System.gc(): the collector self-tunes.
        log.info(() -> "No System.gc() called — pooling + try-with-resources used instead");
        log.info(() -> "Rajesh Rs." + rajesh.getBalance() + ", Priya Rs." + priya.getBalance());
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in ConnectionPool.java (object pooling) ───
class ConnectionPool {
    private static final Logger log = Logger.getLogger("BankLog");
    private final java.util.Deque<PooledLedgerConnection> idle = new java.util.ArrayDeque<>();

    ConnectionPool(int size) {
        for (int i = 0; i < size; i++) idle.add(new PooledLedgerConnection("conn-" + i, this));
        log.info(() -> "Pool created with " + size + " reusable connections");
    }
    // Borrow reuses an existing connection instead of allocating a new one.
    PooledLedgerConnection borrow() {
        PooledLedgerConnection c = idle.pollFirst();
        return (c != null) ? c : new PooledLedgerConnection("conn-overflow", this);
    }
    void giveBack(PooledLedgerConnection c) { idle.addLast(c); }
}

// ─── Would be in PooledLedgerConnection.java (AutoCloseable) ───
class PooledLedgerConnection implements AutoCloseable {
    private static final Logger log = Logger.getLogger("BankLog");
    private final String id;
    private final ConnectionPool pool;

    PooledLedgerConnection(String id, ConnectionPool pool) { this.id = id; this.pool = pool; }

    void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        log.info(() -> id + " transferred Rs." + amount);
    }
    @Override
    public void close() {
        // Returned to the pool deterministically, NOT left for GC.
        pool.giveBack(this);
    }
}
